create table support_queues (id bigserial primary key,system_id bigint not null references saas_systems(id),name varchar(120) not null,slug varchar(120) not null,category varchar(60),default_priority varchar(20) not null default 'normal',first_response_hours integer not null default 8,resolution_hours integer not null default 48,active boolean not null default true,created_at timestamp default current_timestamp,unique(system_id,slug));
alter table support_tickets add column if not exists queue_id bigint null references support_queues(id);
create index if not exists support_tickets_queue_status_idx on support_tickets(queue_id,status,priority);
create table ai_chat_configs (id bigserial primary key,system_id bigint not null unique references saas_systems(id),provider varchar(40) not null default 'disabled',model varchar(100),credential_env_key varchar(100),temperature numeric(4,2) not null default 0.20,max_output_tokens integer not null default 800,min_confidence numeric(4,2) not null default 0.70,rag_enabled boolean not null default true,fallback_queue_id bigint references support_queues(id),system_prompt text,active boolean not null default false,updated_by bigint references admin_users(id),created_at timestamp default current_timestamp,updated_at timestamp);
insert into support_queues(system_id,name,slug,category) select id,'Atendimento geral','geral','general' from saas_systems on conflict(system_id,slug) do nothing;
insert into ai_chat_configs(system_id,provider,active) select id,'disabled',false from saas_systems on conflict(system_id) do nothing;
